// ── ВСТРОЕННЫЕ SVG-ИЗОБРАЖЕНИЯ ──
// Не зависят от внешних CDN — работают везде, включая GitHub Pages.
// Заменить на реальные фото когда клиент предоставит материалы:
// просто поменять значения IMG.* на пути к файлам из папки img/.

const IMG = {
  // Фото аккумулятора — используется в карточках товаров, на странице товара, в герое
  battery: `data:image/jpeg;base64,`,

  // Фото для героя и фонов страниц
  heroBg: `data:image/jpeg;base64,`,
  heroBg2: `data:image/jpeg;base64,`,
  heroBg3: `data:image/jpeg;base64,`,
  heroBg4: `data:image/jpeg;base64,`,
  heroBg5: `data:image/jpeg;base64,`,
  heroBg6: `data:image/jpeg;base64,`,
  heroBgAbout: `data:image/jpeg;base64,`,

};

// ── ИКОНКИ ──
// Инлайном, а не файлами: иконки перекрашиваются через currentColor
// (в шапке чёрные, в тёмном меню белые) и не дают лишних запросов.
const ICON_SEARCH = '<svg viewBox="0 0 20 20" fill="none" aria-hidden="true" focusable="false">' +
  '<circle cx="9" cy="9" r="6.2" stroke="currentColor" stroke-width="1.8"/>' +
  '<path d="M13.6 13.6L18.2 18.2" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg>';

